// Known public contracts, generated by scripts/build-known-contracts.py from
// engine/data/known-contracts.json. A hit says the address is a contract whose
// deployment the project itself published; it never says a request is safe.
import library from '../data/known-contracts.engine.json' with { type: 'json' };
// Rows are one string: networkIndex, address, name, protocol, categoryIndex.
// Split on first use, so a VM that signs a plain transfer never pays for it.
let index;
const EVERY_EVM = 'evm:*';
const table = () => index ??= library.contracts.split('\n').reduce((map, row) => {
  const [network, address, name, protocol, category] = row.split('\t');
  map.set(library.networks[+network] + '/' + address,
          Object.freeze({ address, name, protocol, category: library.categories[+category],
                          network: library.networks[+network] }));
  return map;
}, new Map());

/** EVM addresses compare lowercased; TRON and Solana keep their case. */
function normalize(chainFamily, address) {
  if (typeof address !== 'string' || !address) return undefined;
  return chainFamily === 'evm' ? address.toLowerCase() : address;
}

/**
 * The library entry for a contract, or undefined. `chainId` is only read for
 * EVM; a contract that is not listed for this chain is still looked up under
 * the deterministic (CREATE2) entries that are the same address everywhere.
 */
export function lookupContract(chainFamily, chainId, address) {
  const key = normalize(chainFamily, address);
  if (!key) return undefined;
  const found = table().get(`${chainFamily}:${chainFamily === 'evm' ? chainId ?? '' : ''}/${key}`);
  if (found) return { ...found, everyChain: false };
  if (chainFamily !== 'evm') return undefined;
  const universal = table().get(`${EVERY_EVM}/${key}`);
  return universal ? { ...universal, everyChain: true } : undefined;
}

/** What the review shows for the counterparty of a request. */
export function describeContract(chainFamily, chainId, address, role) {
  if (typeof address !== 'string' || !address) return undefined;
  const known = lookupContract(chainFamily, chainId, address);
  return known ? { address, role, known: true, name: known.name, protocol: known.protocol,
                   category: known.category, everyChain: known.everyChain }
               : { address, role, known: false };
}

export const knownContractsUpdated = library.updated;
export const knownContractCount = library.count;
